import type { Metadata } from "next";

import { absoluteUrl, SITE } from "./site";

/**
 * Per-page metadata with its own canonical URL, og:url and Open Graph card (spec §8).
 * `og` names a card in public/og/ generated by `pnpm og`.
 */
export function pageMetadata({
  title,
  description = SITE.description,
  path,
  og,
}: {
  title?: string;
  description?: string;
  path: string;
  og: string;
}): Metadata {
  const url = absoluteUrl(path);
  const fullTitle = title ? `${title} | ${SITE.name}` : `${SITE.name}: Mission Control`;
  const image = { url: `/og/${og}.png`, width: 1200, height: 630, alt: fullTitle };
  return {
    title: title ?? { absolute: fullTitle },
    description,
    alternates: { canonical: url },
    openGraph: {
      title: fullTitle,
      description,
      url,
      siteName: SITE.name,
      type: "website",
      locale: "en_GB",
      images: [image],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [image.url] },
  };
}
